import { redirect } from "next/navigation";
import { AuthError } from "next-auth";

import { signIn } from "@/auth";
import { createUserWithPassword } from "@/lib/users";

export async function signUp(formData: FormData) {
  const name = String(formData.get("name") ?? "").trim();
  const email = String(formData.get("email") ?? "").trim();
  const password = String(formData.get("password") ?? "");
  const confirmPassword = String(formData.get("confirmPassword") ?? "");

  if (!email || !password) {
    redirect("/sign-up?error=missing-fields");
  }
  if (password.length < 8) {
    redirect("/sign-up?error=weak-password");
  }
  if (password !== confirmPassword) {
    redirect("/sign-up?error=password-mismatch");
  }

  try {
    await createUserWithPassword(email, name, password);
  } catch {
    redirect("/sign-up?error=email-taken");
  }

  try {
    await signIn("credentials", {
      email,
      password,
      redirectTo: "/dashboard",
    });
  } catch (error) {
    if (error instanceof AuthError) {
      // Account was created fine; something odd happened signing in —
      // send them to sign in manually instead of losing the new account.
      redirect("/sign-in?error=CredentialsSignin");
    }
    throw error;
  }
}

