import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

// Internal record. `passwordHash` is null for accounts that only ever signed
// in with an OAuth provider (e.g. Google) and never set a password.
type StoredUser = User & {
  passwordHash: string | null;
};

// NOTE: this is the same in-memory store the scaffold started with. It does
// not persist across deploys/restarts and is not shared across Cloudflare
// Workers instances/regions — fine for this exercise, but a real deployment
// should back this with D1, KV, or another durable store behind the same
// function signatures below.
const users: StoredUser[] = [
  {
    id: "1",
    email: "ada@example.com",
    name: "Ada",
    createdAt: "2026-01-04",
    passwordHash: null,
  },
  {
    id: "2",
    email: "grace@example.com",
    name: "Grace",
    createdAt: "2026-02-11",
    passwordHash: null,
  },
];

let nextId = users.length + 1;

function toPublicUser({ passwordHash: _passwordHash, ...user }: StoredUser): User {
  return user;
}

function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

export async function listUsers(): Promise<User[]> {
  return users.map(toPublicUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const user = users.find((u) => u.id === id);
  return user ? toPublicUser(user) : undefined;
}

export async function findUserByEmail(email: string): Promise<User | undefined> {
  const normalized = normalizeEmail(email);
  const user = users.find((u) => u.email.toLowerCase() === normalized);
  return user ? toPublicUser(user) : undefined;
}

/**
 * Creates a new account with an email/password. Throws if the email is
 * already taken. Used by the sign-up flow.
 */
export async function createUserWithPassword(
  email: string,
  name: string,
  password: string,
): Promise<User> {
  const normalized = normalizeEmail(email);
  if (users.some((u) => u.email.toLowerCase() === normalized)) {
    throw new Error("An account with that email already exists.");
  }

  const passwordHash = await bcrypt.hash(password, 10);
  const user: StoredUser = {
    id: String(nextId++),
    email: normalized,
    name: name.trim() || normalized,
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash,
  };
  users.push(user);
  return toPublicUser(user);
}

/**
 * Verifies email/password credentials for sign-in. Returns the public user
 * on success, or null if the email is unknown, the account has no password
 * (OAuth-only), or the password doesn't match.
 */
export async function verifyPassword(
  email: string,
  password: string,
): Promise<User | null> {
  const normalized = normalizeEmail(email);
  const user = users.find((u) => u.email.toLowerCase() === normalized);
  if (!user || !user.passwordHash) return null;

  const valid = await bcrypt.compare(password, user.passwordHash);
  return valid ? toPublicUser(user) : null;
}

/**
 * Finds the account for an OAuth sign-in (e.g. Google), creating one on
 * first sign-in. OAuth-only accounts have no password set.
 */
export async function findOrCreateOAuthUser(profile: {
  email: string;
  name?: string | null;
}): Promise<User> {
  const normalized = normalizeEmail(profile.email);
  const existing = users.find((u) => u.email.toLowerCase() === normalized);
  if (existing) return toPublicUser(existing);

  const user: StoredUser = {
    id: String(nextId++),
    email: normalized,
    name: profile.name?.trim() || normalized,
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash: null,
  };
  users.push(user);
  return toPublicUser(user);
}

